import struct, zlib
def write_gray(path, W, H, fn):
    raw = b''
    for y in range(H):
        raw += b'\x00' + bytes(fn(x,y) for x in range(W))
    def chunk(t, d):
        return struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t+d)&0xffffffff)
    png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', W,H,8,0,0,0,0)) + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b'')
    open(path,'wb').write(png)
def write_rgb(path, W, H, fn):
    raw = b''
    for y in range(H):
        row = b''
        for x in range(W):
            r,g,b = fn(x,y); row += bytes((r,g,b))
        raw += b'\x00' + row
    def chunk(t, d):
        return struct.pack('>I', len(d)) + t + d + struct.pack('>I', zlib.crc32(t+d)&0xffffffff)
    png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', W,H,8,2,0,0,0)) + chunk(b'IDAT', zlib.compress(raw)) + chunk(b'IEND', b'')
    open(path,'wb').write(png)
